import Image from "next/image";
import Link from "next/link";
import { brand } from "@/config/brand";
import { cn } from "@/lib/cn";

// Official OmniHack logos. Originals live in design/brand/; web versions are generated by
// scripts/brand-assets.mjs into public/brand/ (dark-on-light and light-on-dark variants).

/** The symbol on its own (bracketed diamond with "hi"), for compact spaces. */
export function LogoMark({ className, title }: { className?: string; title?: string }) {
  return <Image src="/brand/omnihack-mark.png" alt={title ?? ""} width={512} height={512} className={cn("h-8 w-8", className)} />;
}

/** Horizontal lockup: symbol + "OMNIHack" wordmark. Use `inverted` on dark backgrounds. */
export function Logo({ className, inverted = false, href = "/" }: { className?: string; inverted?: boolean; href?: string | null }) {
  const content = (
    <Image
      src={inverted ? "/brand/omnihack-logo-light.png" : "/brand/omnihack-logo.png"}
      alt={brand.name}
      width={877}
      height={160}
      priority
      className={cn("h-8 w-auto", className)}
    />
  );
  if (!href) return content;
  return (
    <Link href={href} aria-label={`${brand.name} home`} className="inline-flex rounded-md">
      {content}
    </Link>
  );
}
